from lib import *
S = SS('e9')
steps = [
    step("0 阶熵只看每个字节出现的频率,给出“不看上下文”的体积下限 = 熵 × 字节数 / 8。每份 1 MiB:随机字节熵 8.000 bit/字节,下限 1048553,所有压缩器都压不动(gzip 1048902、zstd-19 1048688);随机小写字母熵 4.700,下限 616094,zstd-3 625783(只多 1.6%);词表拼接熵 4.228,下限 554220,zstd-19 312360 已经远低于下限;products JSON Lines 熵 5.135,下限 673018,zstd-19 153604、xz-9 113026;类 HTML 页面下限 635962,xz-9 129572。能比 0 阶下限小很多,是因为压缩器还利用了前后文的重复。", t=tl(S(1)), done=lidx(S(1), 'products JSON Lines'), mark=lidx(S(1), '随机字节'), b=bars([['随机字节 0 阶下限', 1048553, '1048553'], ['随机字节 zstd-19', 1048688, '1048688'], ['products 0 阶下限', 673018, '673018'], ['products zstd-19', 153604, '153604'], ['products xz-9', 113026, '113026']], 1050000, mark=[1], done=[3, 4]), kv=KV([['随机字节', '熵 8.000,谁也压不动'], ['products JSON Lines', '0 阶下限 673018,xz-9 做到 113026'], ['原因', '压缩器还利用了前后文']], ['原因'])),
    step("条件熵:已知前面 k 个字节时,下一个字节还剩多少不确定(products 的 1 MiB):k=0 为 5.135 bit/字节(下限 673018),k=1 为 3.034(397667),k=2 为 1.780(233267),k=3 为 1.050(137612),k=4 为 0.734(96149)。对照 zstd-19 实际 165377 字节 = 1.262 bit/字节,xz-9 153604 字节 = 1.172 bit/字节。上下文越长越确定:压缩的本质就是利用“前面出现过什么”。但样本只取 64 KiB 时 k=4 的经验熵是 0.521(1 MiB 时 0.734)——样本太少,每种上下文只见过几次,熵被低估,不是真的可压缩那么多。", t=tl(S(2)), done=lidx(S(2), '对照:zstd-19 实际'), mark=lidx(S(2), '   4 '), b=bars([['k=0 bit/字节', 5.135, '5.135'], ['k=1', 3.034, '3.034'], ['k=2', 1.780, '1.780'], ['k=3', 1.050, '1.050'], ['k=4', 0.734, '0.734']], 5.2, done=[3, 4], mark=[0]), kv=KV([['k=0 → k=4', '5.135 → 0.734 bit/字节'], ['zstd-19 实际', '1.262 bit/字节'], ['小样本', '64 KiB 时 k=4 低估到 0.521']], ['zstd-19 实际'])),
    step("不可能全部变小:枚举全部长度 0–2 的字节串(65793 个)加 10 万个随机长度 3 的字节串,共 165793 个。zlib、zstd-3、lz4 frame、lz4 block 四种压缩器,变短 0 个、相等 0 个、变长 165793 个;压缩 1 字节 b\"a\",zlib 得到 9 字节,zstd 10 字节,lz4 frame 24 字节,lz4 block 2 字节。长度小于 3 的字节串一共 65793 个,长度为 3 的有 16777216 个,不可能每个都映射到更短的串。压缩器能让“有规律”的数据变短,代价是别的数据变长——对随机数据一定是净亏损。", t=tl(S(3)), done=lidx(S(3), 'zstd-3'), mark=lidx(S(3), 'zlib(gzip'), b=bars([['变短', 0, '0'], ['相等', 0, '0'], ['变长', 165793, '165793']], 170000, mark=[2], done=[0, 1]), kv=KV([['165793 个短字节串', '没有一个变短'], ['压缩 b"a"', 'zlib 9 / zstd 10 / lz4 frame 24 字节'], ['原因', '计数:短串的个数少于长串']], ['原因'])),
    step("已知熵的信源(每份 1 MiB 个独立同分布的符号):0.5/0.5 两个符号,熵 1.0000,下限 131072,zstd-19 132495(多 1.1%);0.9/0.1,熵 0.4690,下限 61472,zstd-19 76235(多 24.0%),xz-9 75564,bz2-9 75187;0.99/0.01,熵 0.0808,下限 10589,zstd-19 17630(多 66.5%),xz-9 21252,bz2-9 11816;4 个符号均匀(熵 2)和 16 个符号均匀(熵 4)zstd-19 只多 0.5% 与 0.2%。符号概率接近均匀时压缩器几乎贴着理论值;概率很不均匀(一个符号占 99%)时离理论值还很远——这是 Huffman 每个符号至少要 1 位的限制,下面讲 FSE/ANS 怎么解决。", t=tl(S(4)), done=lidx(S(4), '两个符号 0.5/0.5'), mark=lidx(S(4), '两个符号 0.99/0.01'), b=bars([['0.5/0.5 zstd 超出下限 %', 1.1, '1.1'], ['0.9/0.1 超出 %', 24.0, '24.0'], ['0.99/0.01 超出 %', 66.5, '66.5'], ['16 符号均匀 超出 %', 0.2, '0.2']], 70, done=[0, 3], mark=[1, 2]), kv=KV([['均匀分布', 'zstd-19 贴着理论值(多 0.2–1.1%)'], ['0.99/0.01', 'zstd-19 多 66.5%,bz2 只多 11.6%'], ['原因', 'Huffman 每个符号至少 1 位']], ['原因'])),
    step("能用很短的程序生成,不等于能被压缩:random.Random(1).randbytes(1 << 20) 只有 35 个字符,但生成的 1 MiB 伪随机字节,gzip-9 压成 1048902、zstd-19 1048609、xz-9 1048688、bz2-9 1053678 字节(原 1048576),谁也压不动。0,1,2,…255 循环的 1 MiB:gzip-9 4396、zstd-19 358;i*i 取低 8 位的 1 MiB:gzip-9 3719、zstd-19 218。压缩器能发现的是重复和统计偏斜,看不出“这是个随机数生成器”。", t=tl(S(5)), done=lidx(S(5), '0,1,2,…255 循环'), mark=lidx(S(5), '伪随机字节'), b=bars([['伪随机 1 MiB zstd-19', 1048609, '1048609'], ['0..255 循环 zstd-19', 358, '358'], ['i*i 低 8 位 zstd-19', 218, '218']], 1050000, mark=[0], done=[1, 2]), kv=KV([['伪随机(种子 1)', '压不动,尽管生成它只要 35 个字符'], ['0..255 循环', 'zstd-19 358 字节'], ['能压的', '重复和统计偏斜']], ['伪随机(种子 1)'])),
    step("换一种表示就改变熵:时间戳十进制文本 549999 字节(0 阶熵 3.185,zstd-19 34403,xz-9 22556);定长 8 字节 400000(50937,23016);差分 varint 50004(0 阶 0.819,zstd-19 6447,xz-9 6308)。价格十进制文本 118458(44968,44320);float64 160000(55822,43644);整数分 varint 41136(39615,35732)。差分把时间戳变成极其集中的几个取值;整数分 varint 编码后的价格 2 阶熵是 1.480 bit/字节,但那是 4 万字节的小样本上 65536 种上下文的假象(第二步),别当成真的下限。编码前先让数据更有规律,压缩才有的放。", t=tl(S(6)), done=lidx(S(6), '时间戳:差分 varint'), mark=lidx(S(6), '时间戳:十进制文本'), b=bars([['时间戳文本 xz-9', 22556, '22556'], ['时间戳定长 xz-9', 23016, '23016'], ['时间戳差分 xz-9', 6308, '6308'], ['价格文本 xz-9', 44320, '44320'], ['价格整数分 xz-9', 35732, '35732']], 46000, mark=[0, 1, 3], done=[2, 4]), kv=KV([['时间戳差分 varint', '50004 字节,压缩后 6308–6447'], ['价格整数分 varint', '41136 字节,压缩后 35732–39615'], ['高阶熵', '小样本上会被低估']], ['时间戳差分 varint'])),
]
A = mkarte('e9', 9, '压缩原理,香农熵,条件熵,不可压缩,鸽巢原理,zstd,xz,bz2,Python,真实验证,动画演示',
    '压缩比的天花板:随机字节熵 8 bit/字节谁也压不动;products 文本 0 阶熵下限 673018 字节、实际 xz-9 做到 113026;已知前 4 个字节条件熵降到 0.734;16.5 万个短字节串压缩后一个都没变短;概率很偏的信源 zstd 离理论值还差 66.5%。',
    '压缩比到底能有多高?上限在哪里,什么数据压不动,压缩器离理论极限有多远?这篇用香农熵、条件熵和已知熵的信源把“高压缩比从哪来”的第一层讲清楚:统计上的偏斜和前后文的规律。',
    [('8.000 对 5.135 bit/字节', '随机字节与 products JSON Lines 的 0 阶熵:前者完全压不动,后者下限 673018 字节'), ('5.135 → 0.734', 'products 文本的条件熵从 0 阶到已知前 4 个字节(bit/字节),实际 zstd-19 是 1.262'), ('0 / 165793', '枚举全部长度 0–2 的字节串加 10 万个随机 3 字节串,压缩后变短的个数(共 165793 个)')],
    [('熵是下限', '<p>香农熵衡量一个信源每个符号至少需要多少位。随机字节是 8 bit/字节,任何压缩器都压不动(1.00×)。只看字节频率(0 阶)的下限对 products 文本是 673018 字节,但真实的压缩器做到 113026–165377,因为还利用了前后文。</p>'),
     ('上下文', '<p>已知前 k 个字节时下一个字节的不确定性越来越小:k=0 是 5.135 bit/字节,k=4 是 0.734。压缩器靠“前面出现过什么”预测接下来的内容。小样本上高阶熵会被严重低估(64 KiB 时 k=4 只有 0.521),因为大部分上下文只见过几次。</p>'),
     ('为什么不可能全部变小', '<p>长度小于 3 的字节串只有 65793 个,长度为 3 的有 16777216 个,不可能每个都对应到一个更短的串。实验里 165793 个短字节串经 zlib、zstd、lz4 压缩,没有一个变短,全部变长。压缩是在“有规律的数据变短,别的数据变长”之间做交换。</p>'),
     ('接近理论值的程度', '<p>符号概率接近均匀时 zstd-19 离理论下限只差 0.2–1.1%;概率很偏时差距变大(0.9/0.1 差 24.0%,0.99/0.01 差 66.5%)。这说明压缩器的熵编码部分(Huffman)在偏斜的分布上浪费很多,第 13 篇讲 FSE/ANS 怎么改进。</p>'),
     ('描述长度不等于压缩', '<p>伪随机数生成器很短(35 个字符),但生成的数据任何通用压缩器都压不动。压缩器能找的只是重复和统计偏斜。</p>'),
     ('表示改变熵', '<p>同一批时间戳,差分之后压缩器能压到 6308–6447 字节,直接压十进制文本要 22556–34403。先把数据变得“有规律”再压缩,这是第 4、8 篇里差分、列存做的事。小样本上的高阶熵不能当真下限。</p>')],
    steps,
    [ENV_E + '。熵是我用经验频率算的(0 到 4 阶);压缩器:gzip(zlib 级别 9)、zstd 3 和 19、xz(lzma 预设 9)、bz2 级别 9、lz4;信源按指定概率用固定种子生成;所有数字都是确定性的字节数',
     '没有验证:算术编码或 PPM、CM 这类更强的上下文建模压缩器(它们能更接近条件熵);更大样本下的高阶熵(1 MiB 的样本已经让 k=4 偏低);真实自然语言文本;对 JSON 之外格式的熵;理论上 Kolmogorov 复杂度(这里只是用一个例子说明描述长度与可压缩性不同)'],
    '压缩的极限')
